import { tv, type VariantProps } from "tailwind-variants";

export const selectVariants = tv({
  slots: {
    root: "select",
    label: "select__label",
    trigger: "select__trigger",
    value: "select__value",
    icon: "select__icon",
    positioner: "select__positioner",
    popup: "select__popup",
    list: "select__list",
    item: "select__item",
    itemText: "select__item-text",
    itemIndicator: "select__item-indicator",
    scrollUpArrow: "select__scroll-arrow",
    scrollDownArrow: "select__scroll-arrow",
    group: "select__group",
    groupLabel: "select__group-label",
    separator: "select__separator",
    arrow: "select__arrow",
    backdrop: "select__backdrop",
  },
  variants: {
    size: {
      sm: {
        trigger: "select__trigger--sm",
        item: "select__item--sm",
      },
      md: {
        trigger: "select__trigger--md",
        item: "select__item--md",
      },
      lg: {
        trigger: "select__trigger--lg",
        item: "select__item--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type SelectVariants = VariantProps<typeof selectVariants>;

"use client";

import { createContext, useContext } from "react";

import { selectVariants } from "./select.variants";

export type SelectContext = {
  slots: ReturnType<typeof selectVariants>;
};

export const SelectContext = createContext<SelectContext | null>(null);

export const useSelectContext = () => {
  const context = useContext(SelectContext);
  return context ?? { slots: selectVariants() };
};

.select {
  @apply text-foreground flex flex-col gap-1.5;
}

.select__label {
  @apply text-foreground cursor-default text-sm font-medium;
}

.select__trigger {
  @apply border-input bg-background placeholder:text-muted-foreground focus-visible:outline-ring data-invalid:border-destructive flex h-9 w-full min-w-40 items-center justify-between gap-2 rounded-md border px-3 py-2 text-sm shadow-xs transition-colors select-none focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.select__trigger--sm {
  @apply h-8 px-2 text-xs;
}

.select__trigger--md {
  @apply h-9 px-3 text-sm;
}

.select__trigger--lg {
  @apply h-10 px-4 text-base;
}

.select__value {
  @apply data-placeholder:text-muted-foreground truncate;
}

.select__icon {
  @apply text-muted-foreground flex size-4 shrink-0 items-center justify-center;
}

.select__positioner {
  @apply z-50 outline-none select-none;
}

.select__popup {
  @apply border-border bg-popover text-popover-foreground relative min-w-[var(--anchor-width)] overflow-hidden rounded-md border shadow-md transition-all duration-100 ease-out data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0;
}

.select__list {
  @apply relative max-h-60 scroll-py-1 overflow-y-auto p-1;
}

.select__item {
  @apply data-highlighted:bg-accent data-highlighted:text-accent-foreground relative flex cursor-default items-center justify-between rounded-xs px-2 py-1.5 text-sm transition-colors outline-none select-none data-disabled:pointer-events-none data-disabled:opacity-50;
}

.select__item-text {
  @apply truncate;
}

.select__item-indicator {
  @apply text-foreground flex size-4 shrink-0 items-center justify-center;
}

.select__group-label {
  @apply text-muted-foreground px-2 py-1.5 text-xs font-semibold;
}

.select__separator {
  @apply bg-border -mx-1 my-1 h-px;
}

.select__scroll-arrow {
  @apply bg-popover text-muted-foreground flex h-5 w-full cursor-default items-center justify-center text-xs;
}

.select__arrow {
  @apply fill-popover stroke-border;
}

.select__backdrop {
  @apply fixed inset-0 z-40 bg-black/50 transition-opacity duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}
